-- Fixed protected-resource metadata inventory. No credential contents, hashes,
-- Vault identifiers, external account identifiers or Auth principals are read.
-- The three unmapped credential namespaces have UNKNOWN counts, not empty ones.
-- This does not erase/revoke/restore credentials or claim complete tenant scope.
BEGIN;
CREATE FUNCTION public.sandy_tenant_protected_inventory_capture(p_tenant uuid,p_offset integer,p_limit integer) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $capture$
DECLARE spec jsonb;resources jsonb:='{}'::jsonb;page jsonb;metadata jsonb;relation oid;schema_ready boolean;total bigint;items jsonb;page_status text;reason text;next_offset bigint;
BEGIN
 IF p_tenant IS NULL OR p_offset IS NULL OR p_offset<0 OR p_offset>2147483000 OR p_limit IS NULL OR p_limit<1 OR p_limit>50 THEN RAISE EXCEPTION 'tenant_inventory_arguments_invalid';END IF;
 -- Only these literal specifications can reach EXECUTE. No caller-supplied
 -- relation, column, expression, predicate or ordering is interpolated.
 FOR spec IN SELECT value FROM jsonb_array_elements($spec$[{"name":"sandy_operations_keys","ownership":"customer_id","revocation":"dedicated_key_revocation_required_before_purge","retention":"retain_current_revocation_and_audit_evidence","required_columns":{"id":"uuid","customer_id":"uuid","scopes":"text[]","created_at":"timestamp with time zone","last_used_at":"timestamp with time zone","expires_at":"timestamp with time zone","revoked_at":"timestamp with time zone"},"query":"SELECT jsonb_build_object('total_count',(SELECT count(*) FROM public.sandy_operations_keys t WHERE t.customer_id=$1),'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'scopes',t.scopes,'created_at',t.created_at,'last_used_at',t.last_used_at,'expires_at',t.expires_at,'revoked_at',t.revoked_at) ORDER BY t.id),'[]'::jsonb) FROM(SELECT id,scopes,created_at,last_used_at,expires_at,revoked_at FROM public.sandy_operations_keys WHERE customer_id=$1 ORDER BY id LIMIT $3 OFFSET $2)t))"},{"name":"sandy_api_keys","ownership":"separate_api_tenant_namespace","revocation":"ownership_mapping_required_before_revocation","retention":"preserve_unmapped_credentials_and_existing_audit","unavailable_reason":"no_customer_ownership_mapping"},{"name":"sandy_api_credentials","ownership":"owner_principal_credential_namespace","revocation":"preserve_unrelated_owner_principal_credentials","retention":"preserve_unmapped_credentials_and_existing_audit","unavailable_reason":"customer_credential_execution_not_supported"},{"name":"sandy_computer_api_grants","ownership":"separate_api_tenant_namespace","revocation":"ownership_mapping_required_before_revocation","retention":"preserve_current_access_decisions_and_existing_audit","unavailable_reason":"no_customer_ownership_mapping"},{"name":"sandy_context_api_grants","ownership":"customer_id_grantee_not_api_tenant_owner","revocation":"dedicated_authorized_grant_deactivation_required","retention":"preserve_current_access_decisions_and_existing_audit","required_columns":{"id":"uuid","tenant_id":"uuid","customer_id":"uuid","capabilities":"text[]","active":"boolean","created_at":"timestamp with time zone"},"query":"SELECT jsonb_build_object('total_count',(SELECT count(*) FROM public.sandy_context_api_grants t WHERE t.customer_id=$1),'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'api_tenant_id',t.tenant_id,'capabilities',t.capabilities,'active',t.active,'created_at',t.created_at) ORDER BY t.id),'[]'::jsonb) FROM(SELECT id,tenant_id,capabilities,active,created_at FROM public.sandy_context_api_grants WHERE customer_id=$1 ORDER BY id LIMIT $3 OFFSET $2)t))"},{"name":"sandy_calendar_connections","ownership":"customer_id","revocation":"provider_revocation_and_readback_required","retention":"current_policy_and_provider_retention_apply","required_columns":{"id":"uuid","customer_id":"uuid","provider":"text","direction":"text","connection_state":"text","last_sync_at":"timestamp with time zone","created_at":"timestamp with time zone","updated_at":"timestamp with time zone"},"query":"SELECT jsonb_build_object('total_count',(SELECT count(*) FROM public.sandy_calendar_connections t WHERE t.customer_id=$1),'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'provider',t.provider,'direction',t.direction,'connection_state',t.connection_state,'last_sync_at',t.last_sync_at,'created_at',t.created_at,'updated_at',t.updated_at) ORDER BY t.id),'[]'::jsonb) FROM(SELECT id,provider,direction,connection_state,last_sync_at,created_at,updated_at FROM public.sandy_calendar_connections WHERE customer_id=$1 ORDER BY id LIMIT $3 OFFSET $2)t))"},{"name":"sandy_xero_connections","ownership":"owner_customer_id","revocation":"provider_revocation_and_readback_required","retention":"current_policy_and_provider_retention_apply","required_columns":{"id":"uuid","owner_customer_id":"uuid","status":"text","scopes":"text[]","token_expires_at":"timestamp with time zone","last_sync_at":"timestamp with time zone","created_at":"timestamp with time zone","updated_at":"timestamp with time zone"},"query":"SELECT jsonb_build_object('total_count',(SELECT count(*) FROM public.sandy_xero_connections t WHERE t.owner_customer_id=$1),'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'status',t.status,'scopes',t.scopes,'token_expires_at',t.token_expires_at,'last_sync_at',t.last_sync_at,'created_at',t.created_at,'updated_at',t.updated_at) ORDER BY t.id),'[]'::jsonb) FROM(SELECT id,status,scopes,token_expires_at,last_sync_at,created_at,updated_at FROM public.sandy_xero_connections WHERE owner_customer_id=$1 ORDER BY id LIMIT $3 OFFSET $2)t))"},{"name":"sandy_voice_call_links","ownership":"owner_customer_id","revocation":"dedicated_capability_revocation_required_before_purge","retention":"retain_current_revocation_and_audit_evidence","required_columns":{"id":"uuid","owner_customer_id":"uuid","created_at":"timestamp with time zone","expires_at":"timestamp with time zone","revoked_at":"timestamp with time zone","max_starts":"integer","starts":"integer","last_started_at":"timestamp with time zone"},"query":"SELECT jsonb_build_object('total_count',(SELECT count(*) FROM public.sandy_voice_call_links t WHERE t.owner_customer_id=$1),'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'created_at',t.created_at,'expires_at',t.expires_at,'revoked_at',t.revoked_at,'max_starts',t.max_starts,'starts',t.starts,'last_started_at',t.last_started_at) ORDER BY t.id),'[]'::jsonb) FROM(SELECT id,created_at,expires_at,revoked_at,max_starts,starts,last_started_at FROM public.sandy_voice_call_links WHERE owner_customer_id=$1 ORDER BY id LIMIT $3 OFFSET $2)t))"},{"name":"sandy_supabase_tenant_consents","ownership":"tenant_id_confirmed_customer","revocation":"current_consent_never_restored_from_snapshot","retention":"preserve_current_consent_and_immutable_evidence","required_columns":{"tenant_id":"uuid","operations":"text[]","allow_erasure":"boolean","expires_at":"timestamp with time zone","revision":"integer","updated_at":"timestamp with time zone"},"query":"SELECT jsonb_build_object('total_count',(SELECT count(*) FROM public.sandy_supabase_tenant_consents t WHERE t.tenant_id=$1),'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('operations',t.operations,'allow_erasure',t.allow_erasure,'expires_at',t.expires_at,'revision',t.revision,'updated_at',t.updated_at) ORDER BY t.tenant_id),'[]'::jsonb) FROM(SELECT operations,allow_erasure,expires_at,revision,updated_at,tenant_id FROM public.sandy_supabase_tenant_consents WHERE tenant_id=$1 ORDER BY tenant_id LIMIT $3 OFFSET $2)t))"},{"name":"sandy_supabase_tenant_controls","ownership":"tenant_id_confirmed_customer","revocation":"legal_hold_and_retention_are_not_credential_state","retention":"never_release_hold_or_shorten_retention_from_snapshot","required_columns":{"tenant_id":"uuid","legal_hold":"boolean","retention_until":"timestamp with time zone","updated_at":"timestamp with time zone"},"query":"SELECT jsonb_build_object('total_count',(SELECT count(*) FROM public.sandy_supabase_tenant_controls t WHERE t.tenant_id=$1),'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('legal_hold',t.legal_hold,'retention_until',t.retention_until,'updated_at',t.updated_at) ORDER BY t.tenant_id),'[]'::jsonb) FROM(SELECT legal_hold,retention_until,updated_at,tenant_id FROM public.sandy_supabase_tenant_controls WHERE tenant_id=$1 ORDER BY tenant_id LIMIT $3 OFFSET $2)t))"},{"name":"sandy_supabase_managed_vault","ownership":"tenant_id_confirmed_customer","revocation":"dedicated_credential_custody_required_before_purge","retention":"retain_custody_evidence_without_secret_material","required_columns":{"tenant_id":"uuid","name":"text"},"query":"SELECT jsonb_build_object('total_count',(SELECT count(*) FROM public.sandy_supabase_managed_vault t WHERE t.tenant_id=$1),'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.name) ORDER BY t.name COLLATE \"C\"),'[]'::jsonb) FROM(SELECT name FROM public.sandy_supabase_managed_vault WHERE tenant_id=$1 ORDER BY name COLLATE \"C\" LIMIT $3 OFFSET $2)t))"}]$spec$::jsonb) LOOP
  total:=NULL;items:='[]'::jsonb;next_offset:=NULL;
  IF spec ? 'unavailable_reason' THEN
   page_status:='ownership_mapping_unavailable';reason:=spec->>'unavailable_reason';
  ELSE
   page_status:='schema_unavailable';reason:='reviewed_metadata_schema_not_available';
   relation:=to_regclass('public.'||(spec->>'name'));
   SELECT relation IS NOT NULL AND EXISTS(SELECT 1 FROM pg_class WHERE oid=relation AND relkind='r')
    AND NOT EXISTS(SELECT 1 FROM jsonb_each_text(spec->'required_columns') expected
     LEFT JOIN pg_attribute a ON a.attrelid=relation AND a.attname=expected.key AND a.attnum>0 AND NOT a.attisdropped
     WHERE a.attname IS NULL OR format_type(a.atttypid,a.atttypmod) IS DISTINCT FROM expected.value)
   INTO schema_ready;
   IF schema_ready THEN
    EXECUTE spec->>'query' INTO page USING p_tenant,p_offset,p_limit;
    total:=(page->>'total_count')::bigint;items:=page->'items';
    IF total<0 OR total>2147483647 OR jsonb_array_length(items)<>least(p_limit,greatest(total-p_offset,0)) THEN RAISE EXCEPTION 'tenant_inventory_page_bound_or_snapshot_invalid';END IF;
    IF p_offset+jsonb_array_length(items)<total THEN next_offset:=p_offset+jsonb_array_length(items);END IF;
    page_status:='available';reason:=NULL;
   END IF;
  END IF;
  metadata:=jsonb_build_object('ownership',spec->>'ownership','revocation_disposition',spec->>'revocation','retention_disposition',spec->>'retention','generic_restore_permitted',false,
   'offset',p_offset,'limit',p_limit,'status',page_status,'reason',reason,'total_count',total,'items',items,'next_offset',next_offset);
  resources:=resources||jsonb_build_object(spec->>'name',metadata);
 END LOOP;
 RETURN jsonb_build_object('tenant_id',p_tenant,'inventory_version','protected_resource_metadata_v1','observed_at',statement_timestamp(),'offset',p_offset,'limit',p_limit,
  'complete_tenant_coverage',false,'provider_revocation_verified',false,'generic_restore_permitted',false,'audit_evidence_disposition','retain_append_only_digest_evidence','resources',resources);
END $capture$;
CREATE FUNCTION public.sandy_tenant_protected_inventory(p_actor uuid,p_admission uuid,p_canonical text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $inventory$
DECLARE ctx jsonb;args jsonb;tenant uuid;result jsonb;
BEGIN
 -- Existing context proves: enabled owner; current verified exact contract;
 -- consumed one-use approval-bound admission; exact canonical input and scope;
 -- immutable scoped owner approval; current operation-specific customer consent.
 ctx:=public.sandy_tenant_lifecycle_context(p_actor,p_admission,p_canonical);
 args:=ctx->'arguments';tenant:=(ctx->>'tenant_id')::uuid;
 IF ctx->>'operation' IS DISTINCT FROM 'supabase.tenant.protected_resources.inventory'
 OR jsonb_typeof(args) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(args))<>3
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(args) k WHERE k NOT IN('tenant_id','offset','limit'))
 OR tenant IS NULL OR jsonb_typeof(args->'offset') IS DISTINCT FROM 'number' OR jsonb_typeof(args->'limit') IS DISTINCT FROM 'number'
 OR args->>'offset' !~ '^(0|[1-9][0-9]{0,9})$' OR args->>'limit' !~ '^[1-9][0-9]?$'
 OR (args->>'offset')::numeric NOT BETWEEN 0 AND 2147483000 OR (args->>'limit')::numeric NOT BETWEEN 1 AND 50
 THEN RAISE EXCEPTION 'tenant_inventory_arguments_or_operation_invalid';END IF;
 result:=public.sandy_tenant_protected_inventory_capture(tenant,(args->>'offset')::integer,(args->>'limit')::integer);
 IF octet_length(result::text)>1048576 THEN RAISE EXCEPTION 'tenant_inventory_projection_bound_exceeded';END IF;
 RETURN jsonb_build_object('ok',true,'result',result,'reused',false);
END $inventory$;
REVOKE ALL ON FUNCTION public.sandy_tenant_protected_inventory_capture(uuid,integer,integer) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.sandy_tenant_protected_inventory(uuid,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_tenant_protected_inventory(uuid,uuid,text) TO service_role;
